files.content:
:root {
  --bg: #1a1c2c;
  --card: #2b2d42;
  --ink: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #e0a800;
  --muted: #8d99ae;
  --border: #0f1020;
  --focus: #73eff7;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.03) 75%),
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.03) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 0 0 0 4px var(--accent), 8px 8px 0 0 var(--border);
  padding: 28px 24px;
  image-rendering: pixelated;
}

.pixel-title {
  margin: 0 0 24px;
  font-size: 1.75rem;
  letter-spacing: 0.15em;
  text-align: center;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--border);
}

.form {
  display: grid;
  gap: 20px;
}

.field {
  display: grid;
  gap: 8px;
  border: 0;
  padding: 0;
  margin: 0;
}

.field label,
.field legend {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--muted);
  text-transform: uppercase;
}

input[type="number"] {
  width: 100%;
  padding: 12px 14px;
  font-family: inherit;
  font-size: 1.125rem;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: inset 3px 3px 0 0 rgba(0,0,0,0.4);
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px var(--focus), inset 3px 3px 0 0 rgba(0,0,0,0.4);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 14px 8px;
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 4px 4px 0 0 var(--border);
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease, background-color 0.1s ease;
}

.tip-btn:hover {
  background: #33365a;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--border);
  border-color: var(--accent-dark);
}

.tip-btn[aria-pressed="true"]:hover {
  background: #ffd98e;
}

.results {
  margin-top: 28px;
  padding-top: 20px;
  border-top: 4px dashed var(--border);
  display: grid;
  gap: 12px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}

.result-label {
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.result-value {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.result-row.total .result-value {
  color: var(--accent);
  font-size: 1.625rem;
}

@media (max-width: 400px) {
  .card {
    padding: 22px 16px;
  }
  .pixel-title {
    font-size: 1.5rem;
  }
  .tip-btn {
    font-size: 1rem;
    padding: 12px 4px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tip-btn {
    transition: none;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));
  var tipPerPersonEl = document.getElementById('tip-per-person');
  var totalPerPersonEl = document.getElementById('total-per-person');

  var tipPercent = 15;

  function formatCurrency(value) {
    if (!isFinite(value) || value < 0) return '$0.00';
    return '$' + value.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);

    if (!isFinite(bill) || bill < 0) bill = 0;
    if (!isFinite(people) || people < 1) people = 1;

    var tipTotal = bill * (tipPercent / 100);
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = (bill + tipTotal) / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function selectTip(button) {
    tipPercent = parseInt(button.getAttribute('data-tip'), 10);
    tipButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', btn === button ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      selectTip(btn);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  calculate();
})();
